Source code in <code>lyte/control_recording.py</code> <pre><code>class ControlRecorder:
    def __init__(self, path: Path) -&gt; None:
        self.path = path
        self.stream: TextIO | None = None
        self.error: str | None = None
        self.pending: list[MidiEvent | rpc.Request] = []
        self.tick = 0
        self.ordinal = 0
        try:
            self.stream = path.open('x')
        except OSError as error:
            self.fail(error)

    def start(self, config: InstallationFile, library: Library) -&gt; None:
        if self.error is not None:
            return
        try:
            self.write(recording_header(config, library).model_dump_json())
        except (OSError, ValueError) as error:
            self.fail(error)

    def midi(self, message: mido.Message) -&gt; None:
        if self.error is not None:
            return
        self.pending.append(
            MidiEvent(tick=self.tick, ordinal=self.ordinal, data=message.bytes())
        )
        self.ordinal += 1

    def command(self, command: str, params: dict[str, object]) -&gt; None:
        if self.error is not None:
            return
        self.pending.append(rpc.Request(command=command, params=params))

    def delivery(
        self, now: float, counts: dict[str, int], schedule_level: float
    ) -&gt; None:
        if self.error is not None:
            return
        try:
            self.write(
                Delivery(
                    at=now,
                    string_counts=counts,
                    inputs=self.pending,
                    schedule_level=schedule_level,
                ).model_dump_json()
            )
        except ValueError as error:
            self.fail(error)
        self.pending = []
        self.tick += 1

    def write(self, line: str) -&gt; None:
        if self.stream is None:
            return
        try:
            self.stream.write(line + '\n')
            self.stream.flush()
        except (OSError, ValueError) as error:
            self.fail(error)

    def close(self) -&gt; None:
        self.write('{"kind":"end"}')
        if self.stream is None:
            return
        try:
            self.stream.close()
        except (OSError, ValueError) as error:
            self.fail(error)
        finally:
            self.stream = None

    def fail(self, error: OSError | ValueError) -&gt; None:
        if self.error is None:
            LOGGER.error(f'Control recording stopped: {error}')
        self.error = self.error or str(error)
        self.pending.clear()
        if self.stream is not None:
            try:
                self.stream.close()
            except (OSError, ValueError):
                pass
            self.stream = None
</code></pre>

