Source code in <code>lyte/diagnostic_frames.py</code> <pre><code>def dispersed_pixel_order(led_count: int) -&gt; NDArray[np.int64]:
    if led_count &lt;= 0:
        raise ValueError('led_count must be greater than zero')
    if led_count == 1:
        return np.array([0], dtype=np.int64)
    midpoint = led_count / 2
    stride = min(
        (i for i in range(1, led_count) if math.gcd(i, led_count) == 1),
        key=lambda i: (abs(i - midpoint), i),
    )
    return np.fromiter(
        ((i * stride) % led_count for i in range(led_count)),
        dtype=np.int64,
        count=led_count,
    )
