Source code in <code>lyte/fps_test.py</code> <pre><code>def adjust_black_floor_level(level: RGB, key: str) -&gt; RGB:
    red, green, blue = level
    if key == 'r':
        red = min(255, red + 1)
    elif key == 'g':
        green = min(255, green + 1)
    elif key == 'b':
        blue = min(255, blue + 1)
    elif key == 'R':
        red = max(0, red - 1)
    elif key == 'G':
        green = max(0, green - 1)
    elif key == 'B':
        blue = max(0, blue - 1)
    elif key == UP_KEY:
        red = min(255, red + 1)
        green = min(255, green + 1)
        blue = min(255, blue + 1)
    elif key == DOWN_KEY:
        red = max(0, red - 1)
        green = max(0, green - 1)
        blue = max(0, blue - 1)
    return red, green, blue
