Source code in <code>lyte/rehearsal_http.py</code> <pre><code>def handler(session: RehearsalSession) -&gt; type[BaseHTTPRequestHandler]:
    class RehearsalHandler(BaseHTTPRequestHandler):
        def setup(self) -&gt; None:
            self.request.settimeout(5)
            super().setup()

        def do_GET(self) -&gt; None:
            if self.path != '/':
                self.send_error(404)
                return
            data = REHEARSAL_TEMPLATE.encode()
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.send_header('Content-Length', str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def do_POST(self) -&gt; None:
            if self.path != '/api/rehearse':
                self.send_error(404)
                return
            status = 200
            try:
                request = RehearsalRequest.model_validate_json(
                    http_body.read_body(self)
                )
                result = session.request(request)
            except TimeoutError as error:
                status = 408
                result = {'error': str(error)}
            except OSError as error:
                status = 503
                result = {'error': str(error)}
            except (ValueError, TypeError, KeyError) as error:
                status = 400
                result = {'error': str(error)}
            data = json.dumps(result).encode()
            self.send_response(status)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def log_message(self, format: str, *args: object) -&gt; None:
            return

    return RehearsalHandler
