Source code in <code>lyte/render.py</code> <pre><code>def parse_color(value: str) -&gt; tuple[int, int, int]:
    if (name := value.casefold()) in _COLORS:
        return _COLORS[name]
    if value.startswith('#') and len(value) in {4, 7}:
        digits = value[1:]
        if len(digits) == 3:
            digits = ''.join(digit * 2 for digit in digits)
        try:
            return (
                int(digits[0:2], 16),
                int(digits[2:4], 16),
                int(digits[4:6], 16),
