    self, device: animation.Device, state: SearchlightsState
) -&gt; NDArray[np.float32]:
    frame = np.zeros((device.led_count, 3), dtype=np.float32)
    end = validators.resolve_end(device.led_count, self.end)
    fade = 256 / state.tail
    for i in range(3):
