Source code in <code>lyte/twinkly/diagnostic.py</code> <pre><code>def read_endpoint(
    client: TwinklyClient,
    retry: RetryConfig,
    name: str,
    method: str,
    path: str,
    request: Callable[[], dict[str, object]],
) -&gt; TwinklyEndpointReport:
    def read_once() -&gt; TwinklyEndpointReport:
        try:
            return TwinklyEndpointReport(
                name=name,
                path=path,
                supported=True,
                data=request(),
            )
        except UnsupportedEndpointError as err:
            return TwinklyEndpointReport(
                name=name,
                path=path,
                supported=False,
                error=err.text,
            )

    result = retry_call(
        session.twinkly_request_label(method, path, client.host),
        retry,
        read_once,
        (AuthenticationError, ProtocolError),
    )
    if result is not None:
        return result
    return TwinklyEndpointReport(
        name=name,
        path=path,
        supported=False,
        error='request failed',
    )
